
const DATA={"questions": [{"topic": "Adquisiciones", "prompt": "¿Qué proceso incluye cerrar contratos en PMBOK 6?", "options": ["Efectuar adquisiciones", "Planificar adquisiciones", "Estimar costos", "Controlar adquisiciones"], "answer": 3, "explanation": "El capítulo 12 integra cierre y seguimiento contractual en Controlar las Adquisiciones."}, {"topic": "Adquisiciones", "prompt": "Necesitas explorar proveedores y tecnologías antes de fijar una compra. ¿Documento?", "options": ["RFI", "RFQ", "Acta de aceptación", "Orden de pago"], "answer": 0, "explanation": "RFI solicita información del mercado; después puedes preparar una cotización o propuesta."}, {"topic": "Adquisiciones", "prompt": "Se busca resolver un problema técnico con distintos enfoques posibles. ¿Solicitud apropiada?", "options": ["Informe de cierre", "RFP", "Factura", "RFQ centrada solo en precio"], "answer": 1, "explanation": "Una RFP solicita propuestas de solución, enfoque técnico y condiciones."}, {"topic": "Adquisiciones", "prompt": "¿Qué define el SOW de una adquisición?", "options": ["Solo el precio máximo", "Solo el calendario de pagos", "Trabajo y resultados incluidos en ese contrato", "Todo el portafolio empresarial"], "answer": 2, "explanation": "El enunciado del trabajo precisa alcance contratado, calidad, cantidades, plazos y servicios."}, {"topic": "Adquisiciones", "prompt": "Alcance estable y producto bien definido. ¿Tipo coherente?", "options": ["CPAF por defecto", "T&M ilimitado", "CPFF obligatorio", "FFP"], "answer": 3, "explanation": "Precio fijo cerrado es adecuado cuando hay buena definición; cambios de alcance siguen el procedimiento contractual."}, {"topic": "Adquisiciones", "prompt": "¿Qué permanece fijo en CPFF si el alcance no cambia?", "options": ["El honorario pactado", "El total de costos reembolsados", "Toda la factura final", "El costo de cada recurso"], "answer": 0, "explanation": "Costo más honorarios fijos reembolsa costos autorizados más un honorario fijo."}, {"topic": "Adquisiciones", "prompt": "¿Qué diferencia FPIF de FFP?", "options": ["Reembolso irrestricto", "Incentivos por desempeño y precio tope", "Pago exclusivo por horas", "Ausencia de obligación de entrega"], "answer": 1, "explanation": "FPIF permite incentivos según métricas y fija un precio máximo."}, {"topic": "Adquisiciones", "prompt": "Contrato largo expuesto a inflación con ajustes definidos. ¿Tipo?", "options": ["T&M sin límite", "CPFF", "FPEPA", "CPAF"], "answer": 2, "explanation": "Precio fijo con ajuste económico contempla mecanismos de ajuste previamente pactados."}, {"topic": "Adquisiciones", "prompt": "¿Qué riesgo conserva el comprador en T&M?", "options": ["Imposibilidad de fijar tarifas", "Pago total fijo por definición", "Ausencia de supervisión", "Cantidad de horas y costo total variable"], "answer": 3, "explanation": "Las tarifas pueden ser fijas, pero el total depende de cantidades; convienen topes y control."}, {"topic": "Adquisiciones", "prompt": "Objetivo de costo 1.000, honorario 100, vendedor recibe 20 % del ahorro; real 900. ¿Pago sin otros límites?", "options": ["1.020", "900", "1.100", "1.080"], "answer": 0, "explanation": "Ahorro=100; incentivo=20; honorario=120; pago=900+120."}, {"topic": "Adquisiciones", "prompt": "¿Qué beneficio tiene una conferencia de oferentes?", "options": ["Garantizar menor precio", "Entendimiento común y trato equitativo", "Adjudicar antes de recibir ofertas", "Cambiar criterios sin informar"], "answer": 1, "explanation": "Aclara requisitos y consultas para los potenciales vendedores."}, {"topic": "Adquisiciones", "prompt": "Dos proveedores tienen precios iniciales distintos. ¿Evaluación más completa?", "options": ["Número de empleados como criterio exclusivo", "Cambiar ponderaciones tras ver las ofertas", "Criterios publicados y costo del ciclo de vida", "Precio inicial como único criterio siempre"], "answer": 2, "explanation": "La selección considera requisitos técnicos, riesgo, operación y costos relevantes."}, {"topic": "Adquisiciones", "prompt": "¿Qué hacer ante discrepancia sobre compensación de un cambio?", "options": ["Pagar sin verificar", "Cerrar unilateralmente como rutina", "Modificar línea base sin autorización", "Documentar reclamación y aplicar mecanismos contractuales"], "answer": 3, "explanation": "Las reclamaciones se documentan y gestionan; se prioriza negociación y mecanismos del acuerdo."}, {"topic": "Adquisiciones", "prompt": "¿Qué evidencia permite el cierre normal?", "options": ["Entregables aceptados, obligaciones y pagos resueltos, notificación formal", "Solo software ejecutable", "Solo una reunión interna", "Solo consumo del presupuesto"], "answer": 0, "explanation": "El administrador autorizado verifica condiciones contractuales y comunica cierre formal."}, {"topic": "Adquisiciones", "prompt": "¿Qué analiza hacer o comprar?", "options": ["Solo la depreciación", "Costo completo, capacidad, riesgo y tiempo", "Solo el precio del equipo", "Solo la cantidad de proveedores"], "answer": 1, "explanation": "Incluye costos de oportunidad, capacidad disponible y consecuencias del suministro."}, {"topic": "Costos", "prompt": "Una estimación usa 300 HH a 0,5 UF/HH. ¿Técnica y monto?", "options": ["Ascendente, 600 UF", "PERT, 150 UF", "Paramétrica, 150 UF", "Análoga, 150 UF"], "answer": 2, "explanation": "Se aplica un parámetro unitario a una cantidad."}, {"topic": "Costos", "prompt": "PERT con optimista 80, probable 110 y pesimista 200 da…", "options": ["130 UF", "110 UF", "160 UF", "120 UF"], "answer": 3, "explanation": "(80 + 4×110 + 200)/6 = 120."}, {"topic": "Costos", "prompt": "¿Qué reserva integra la línea base de costos?", "options": ["Contingencia", "Gestión completa", "Utilidad del proveedor", "Intereses futuros por defecto"], "answer": 0, "explanation": "La contingencia cubre riesgos identificados; gestión integra el presupuesto total."}, {"topic": "Costos", "prompt": "BAC 2.000, avance real ponderado 35 %. ¿EV?", "options": ["2.000 UF", "700 UF", "1.300 UF", "Depende del AC"], "answer": 1, "explanation": "EV valora el trabajo realizado a precios del presupuesto: 2.000×0,35."}, {"topic": "Costos", "prompt": "Una actividad cuesta 900 y dura meses 4 a 6 uniformemente. ¿PV al cierre del mes 5?", "options": ["900 UF", "450 UF", "600 UF", "500 UF"], "answer": 2, "explanation": "Han transcurrido dos de sus tres meses planificados: 900×2/3."}, {"topic": "Costos", "prompt": "Una actividad futura se inicia antes y completa 10 %. ¿Cómo afecta al corte?", "options": ["Suma PV automáticamente", "No suma EV hasta su mes planificado", "Solo aumenta BAC", "Suma EV y AC; su PV sigue según el plan"], "answer": 3, "explanation": "PV depende de la línea base; EV recoge avance real autorizado incluso anticipado."}, {"topic": "Costos", "prompt": "EV 800, AC 1.000, PV 700. ¿Diagnóstico?", "options": ["Adelantado con sobrecosto", "Atrasado con ahorro", "Adelantado con ahorro", "Atrasado con sobrecosto"], "answer": 0, "explanation": "SV=100 y CV=−200. Cronograma compara EV con PV; costo con AC."}, {"topic": "Costos", "prompt": "CPI 0,8 significa…", "options": ["80 % del presupuesto disponible", "0,8 UF de trabajo presupuestado por UF gastada", "80 % de avance total", "20 % de atraso temporal"], "answer": 1, "explanation": "CPI=EV/AC mide eficiencia de costo."}, {"topic": "Costos", "prompt": "SPI 0,8 permite afirmar…", "options": ["Falta 20 % de días", "El AC supera BAC en 20 %", "Se ejecutó 80 % del valor previsto a la fecha", "El proyecto lleva 80 % de avance total"], "answer": 2, "explanation": "SPI compara trabajo ejecutado con planificado al mismo corte."}, {"topic": "Costos", "prompt": "BAC 1.000, EV 400, AC 500. Resto al costo original. ¿EAC?", "options": ["1.250 UF", "900 UF", "600 UF", "1.100 UF"], "answer": 3, "explanation": "EAC=AC+(BAC−EV)=500+600."}, {"topic": "Costos", "prompt": "Mismos datos, persiste eficiencia de costo. ¿EAC?", "options": ["1.250 UF", "1.100 UF", "800 UF", "1.500 UF"], "answer": 0, "explanation": "CPI=400/500=0,8; EAC=1.000/0,8."}, {"topic": "Costos", "prompt": "BAC 1.000, EV 400, AC 500, SPI 0,75. Influyen ambos índices. ¿EAC?", "options": ["1.000 UF", "1.500 UF", "1.250 UF", "1.100 UF"], "answer": 1, "explanation": "ETC=600/(0,8×0,75)=1.000. EAC=500+1.000."}, {"topic": "Costos", "prompt": "BAC 1.000, EV 400, AC 500. ¿TCPI para BAC?", "options": ["0,6", "1,5", "1,2", "0,8"], "answer": 2, "explanation": "Trabajo faltante 600 dividido por fondos restantes 500."}, {"topic": "Costos", "prompt": "BAC 1.000, EV 400, AC 500, EAC 1.300. Meta revisada. ¿TCPI?", "options": ["1,2", "0,8", "1,3", "0,75"], "answer": 3, "explanation": "Denominador EAC−AC=800. Numerador BAC−EV=600."}, {"topic": "Costos", "prompt": "Se pronostica EAC 1.300 pero se exige terminar con BAC 1.000. TCPI usa…", "options": ["BAC−AC en el denominador", "EAC−AC en el denominador", "BAC−PV en el denominador", "EAC−EV en el denominador"], "answer": 0, "explanation": "La meta exigida decide el denominador, aunque exista otro pronóstico."}, {"topic": "Costos", "prompt": "Paquetes 100 y 900 avanzan 100 % y 0 %. ¿EV?", "options": ["1.000 UF", "100 UF", "500 UF", "900 UF"], "answer": 1, "explanation": "Pondera por presupuesto: 100×1+900×0. El promedio simple de porcentajes distorsiona."}, {"topic": "Costos", "prompt": "EAC 1.500 y AC 600. ¿ETC?", "options": ["600 UF", "1.500 UF", "900 UF", "2.100 UF"], "answer": 2, "explanation": "ETC es lo que falta gastar: EAC−AC."}, {"topic": "Caja", "prompt": "Un estudio ya pagado, irrecuperable, se trata como…", "options": ["Inversión incremental en año 0", "Costo de oportunidad anual", "Recuperación al cierre", "Costo hundido excluido de la decisión futura"], "answer": 3, "explanation": "Ocurrirá el mismo costo histórico con o sin ejecutar la alternativa."}, {"topic": "Caja", "prompt": "Dejar un empleo para emprender implica…", "options": ["Costo de oportunidad de ingresos sacrificados", "Costo hundido", "Depreciación", "Ingreso financiero"], "answer": 0, "explanation": "La decisión sacrifica una alternativa disponible. La pauta incluye esos sueldos en el flujo económico."}, {"topic": "Caja", "prompt": "Capital de trabajo aportado al inicio y recuperable al cierre se registra…", "options": ["Como ingreso inicial", "Negativo al inicio y positivo al cierre", "Gasto anual repetido", "Solo como depreciación"], "answer": 1, "explanation": "Los fondos quedan comprometidos temporalmente."}, {"topic": "Caja", "prompt": "Flujos −100, +60, +60. Nominal y VAN a 10 % son…", "options": ["4,13 y 20", "20 y −4,13", "20 y 4,13", "20 y 20"], "answer": 2, "explanation": "VAN=−100+60/1,1+60/1,1²=4,13."}, {"topic": "Caja", "prompt": "VAN cero significa…", "options": ["No hay ingresos", "La TIR es cero", "Se pierde toda la inversión", "Se alcanza exactamente la tasa exigida"], "answer": 3, "explanation": "El valor actual de cobros netos cubre la inversión y el rendimiento exigido."}, {"topic": "Lecturas", "prompt": "Vendes por 2.500 un activo con valor libro 2.000; impuesto 15 %. ¿Caja neta?", "options": ["2.425", "2.125", "2.500", "2.000"], "answer": 0, "explanation": "Ganancia=500; impuesto=75; venta neta=2.425."}, {"topic": "Caja", "prompt": "Una inversión convencional tiene TIR 14 % y tasa exigida 10 %. Entonces…", "options": ["PRI necesariamente un año", "VAN positivo", "VAN cero", "VAN negativo"], "answer": 1, "explanation": "Para desembolso inicial y cobros posteriores, TIR superior a r implica VAN positivo."}, {"topic": "Lecturas", "prompt": "Venta 3.000, valor libro 4.000, tasa 15 %, base gravable suficiente. Efecto neto de venta…", "options": ["2.850", "4.000", "3.150", "3.000"], "answer": 2, "explanation": "Pérdida contable=1.000; ahorro tributario=150; efecto incremental=3.150."}, {"topic": "Lecturas", "prompt": "IVA recuperable de una compra que se recupera meses después puede…", "options": ["Ser siempre costo depreciable", "Excluirse siempre de tesorería", "Constituir una venta", "Exigir financiamiento temporal"], "answer": 3, "explanation": "El desfase compromete fondos aunque el impuesto se recupere."}, {"topic": "Caja", "prompt": "Depreciación 200 e impuesto 25 %, con utilidad gravable suficiente. Efecto anual tributario…", "options": ["Ahorro de 50", "Salida de caja de 200", "Ingreso por ventas de 50", "Ahorro de 200"], "answer": 0, "explanation": "Reduce impuesto en 200×0,25=50. El desembolso del activo se registra en su compra."}, {"topic": "Lecturas", "prompt": "Proyecto reduce energía de 1.000 a 800; impuesto 20 % y utilidades suficientes. Ahorro neto…", "options": ["240", "160", "200", "40"], "answer": 1, "explanation": "El ahorro bruto aumenta utilidad en 200; el impuesto aumenta 40; quedan 160."}, {"topic": "Lecturas", "prompt": "VP de beneficios 1.200 y VP de costos 1.000. Razón B/C y VAN…", "options": ["1,2 y 1.200", "200 y 1,2", "1,2 y 200", "0,2 y 200"], "answer": 2, "explanation": "Beneficio/costo=1.200/1.000. VAN es diferencia, 200."}, {"topic": "Caja", "prompt": "Préstamo 1.000 al 1 % mensual, 2 meses sin pagos. Deuda…", "options": ["1.020", "1.000", "1.200", "1.020,10"], "answer": 3, "explanation": "Interés capitalizado: 1.000×1,01²."}, {"topic": "Caja", "prompt": "12 % nominal anual con división explícita por 12 implica…", "options": ["1 % mensual", "0,9489 % mensual", "12 % mensual", "1,12 % mensual"], "answer": 0, "explanation": "La convención contractual indicada gobierna. La raíz doce aplica a equivalencia de tasa efectiva."}, {"topic": "Caja", "prompt": "Intereses totales con gracia capitalizada y cuotas iguales…", "options": ["Saldo tras gracia menos última cuota", "Suma de cuotas menos préstamo original", "Suma de cuotas menos saldo tras gracia", "Cuota por tasa mensual"], "answer": 1, "explanation": "Restar el préstamo original incluye intereses de la gracia y de amortización."}, {"topic": "Caja", "prompt": "Con la misma deuda y tasa positiva, más cuotas producen…", "options": ["Igual interés total", "Menor deuda inicial", "Menor cuota y mayor interés total", "Mayor cuota y menor interés"], "answer": 2, "explanation": "La deuda permanece más tiempo generando intereses."}, {"topic": "Lecturas", "prompt": "Resultado operativo después de impuesto 150; capital 1.000; costo de capital 12 %. VEA básico…", "options": ["150", "120", "−30", "30"], "answer": 3, "explanation": "Cargo de capital=120. Valor económico agregado=150−120=30."}, {"topic": "Lecturas", "prompt": "Evaluar un reemplazo mediante flujo incremental requiere…", "options": ["Flujo con proyecto menos flujo sin proyecto", "Solo el costo original hundido", "Sumar íntegramente ambos escenarios", "Excluir la venta del activo antiguo siempre"], "answer": 0, "explanation": "Se identifican cambios en inversión, operación, impuestos, venta y valores finales."}], "lessons": [{"topic": "Pauta 2026", "title": "Los ejercicios que debes dominar", "body": "<h1>Lo que añade la pauta del Control 3 de 2026<\/h1>\n<h2>Costos pertinentes y costo de oportunidad<\/h2>\n<p>Un costo <strong>hundido<\/strong> ya ocurrió y es irrecuperable. El estudio de mercado pagado por 300 UF queda fuera de la decisión futura. Un costo <strong>de oportunidad<\/strong> es lo que sacrificas por elegir el proyecto. Los socios que dejan sueldos por 1.200 UF anuales deben descontarlos en la evaluación económica. Ese sacrificio afecta la conveniencia, aunque no sea un pago de tesorería del negocio.<\/p>\n<p><strong>Recuerda “pasado irrecuperable fuera, alternativa sacrificada dentro”.<\/strong> Para cada partida pregunta qué cambia si aceptas el proyecto.<\/p>\n<h2>La pauta de flujo resuelta<\/h2>\n<p>Inversión inicial = 6.000 equipos + 4.500 desarrollo + 1.500 capital de trabajo = 12.000 UF. Flujo anual = ingresos − operación − costo de oportunidad. Al cierre se agregan 1.500 de capital recuperado y 1.000 de venta de equipos.<\/p>\n<table>\n<thead>\n<tr>\n<th>Año<\/th>\n<th style=\"text-align: right;\">0<\/th>\n<th style=\"text-align: right;\">1<\/th>\n<th style=\"text-align: right;\">2<\/th>\n<th style=\"text-align: right;\">3<\/th>\n<th style=\"text-align: right;\">4<\/th>\n<\/tr>\n<\/thead>\n<tbody>\n<tr>\n<td>Flujo UF<\/td>\n<td style=\"text-align: right;\">−12.000<\/td>\n<td style=\"text-align: right;\">3.000<\/td>\n<td style=\"text-align: right;\">4.000<\/td>\n<td style=\"text-align: right;\">4.800<\/td>\n<td style=\"text-align: right;\">7.800<\/td>\n<\/tr>\n<\/tbody>\n<\/table>\n<p>Nominal = suma de flujos = 7.600 UF. VAN = <math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"−12.000 + 3.000/1,1 + 4.000/1,1² + 4.800/1,1³ + 7.800/1,1⁴\"><mrow><mo>−<\/mo><mn>12.000<\/mn><mo>+<\/mo><mfrac><mn>3.000<\/mn><mn>1,1<\/mn><\/mfrac><mo>+<\/mo><mfrac><mn>4.000<\/mn><msup><mn>1,1<\/mn><mn>2<\/mn><\/msup><\/mfrac><mo>+<\/mo><mfrac><mn>4.800<\/mn><msup><mn>1,1<\/mn><mn>3<\/mn><\/msup><\/mfrac><mo>+<\/mo><mfrac><mn>7.800<\/mn><msup><mn>1,1<\/mn><mn>4<\/mn><\/msup><\/mfrac><\/mrow><\/math> = 2.966,87 UF. <strong>Nominal positivo puede coexistir con VAN negativo.<\/strong> Al reducir a la mitad el ingreso del año 1, el flujo de ese año pasa a −750. El VAN pierde 3.750/1,1 y queda en −442,22 UF.<\/p>\n<h2>Préstamos con meses de gracia<\/h2>\n<p>Durante la gracia sin pagos, el interés se incorpora al saldo. Si el préstamo original es L, la tasa mensual i y hay g meses de gracia, el saldo para calcular cuotas es <strong><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"P = L(1+i)^g\"><mrow><mi>P<\/mi><mo>=<\/mo><mrow><mi>L<\/mi><mo>×<\/mo><msup><mrow><mo>(<\/mo><mrow><mn>1<\/mn><mo>+<\/mo><mi>i<\/mi><\/mrow><mo>)<\/mo><\/mrow><mi>g<\/mi><\/msup><\/mrow><\/mrow><\/math><\/strong>. La primera cuota ocurre al mes siguiente del fin de la gracia.<\/p>\n<p>Luego <strong><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"C = P × i(1+i)^n / [(1+i)^n−1]\"><mrow><mi>C<\/mi><mo>=<\/mo><mrow><mi>P<\/mi><mo>×<\/mo><mfrac><mrow><mi>i<\/mi><mo>×<\/mo><msup><mrow><mo>(<\/mo><mrow><mn>1<\/mn><mo>+<\/mo><mi>i<\/mi><\/mrow><mo>)<\/mo><\/mrow><mi>n<\/mi><\/msup><\/mrow><mrow><msup><mrow><mo>(<\/mo><mrow><mn>1<\/mn><mo>+<\/mo><mi>i<\/mi><\/mrow><mo>)<\/mo><\/mrow><mi>n<\/mi><\/msup><mo>−<\/mo><mn>1<\/mn><\/mrow><\/mfrac><\/mrow><\/mrow><\/math><\/strong>, donde C es cuota mensual y n el número de cuotas. Intereses totales = n×C − L. Se resta el préstamo original para incluir los intereses de la gracia.<\/p>\n<p>En la pauta L=12.000, i=0,01, g=6. Saldo al mes 6 ≈12.738,24. A 12 cuotas, C≈1.131,78; a 18, C≈776,80. Usando cuotas redondeadas, intereses ≈1.581,36 y 1.982,40 UF. Un plazo mayor reduce la cuota y eleva el costo financiero total.<\/p>\n<h2>Valor ganado de la pauta<\/h2>\n<p>BAC=4.000. PV al mes 5=400+600+1.200×2/4+900×2/3=2.200. EV=400+600+480+450+60=1.990. AC=2.340. Integración anticipada suma 60 de EV aunque su PV al corte sea cero.<\/p>\n<p>CV=−350 y SV=−210. CPI=0,8504 y SPI=0,9045. <math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"EAC=AC+(BAC−EV)/(CPI×SPI)\"><mrow><mi>EAC<\/mi><mo>=<\/mo><mrow><mi>AC<\/mi><mo>+<\/mo><mfrac><mrow><mi>BAC<\/mi><mo>−<\/mo><mi>EV<\/mi><\/mrow><mrow><mi>CPI<\/mi><mo>×<\/mo><mi>SPI<\/mi><\/mrow><\/mfrac><\/mrow><\/mrow><\/math>. La pauta informa 4.952,93 UF usando redondeos intermedios. Con los dos índices mostrados y sin redondear su producto resulta aproximadamente 4.953,15 UF; acepta diferencias pequeñas si el procedimiento está justificado.<\/p>\n<p>El patrocinador exige BAC, así que TCPI=(4.000−1.990)/(4.000−2.340)=1,2108. Comparado con CPI≈0,8504, exige mejorar la eficiencia cerca de 42 %. El pronóstico y la meta son dos cantidades diferentes.<\/p>\n<h2>Cómo escribir el desarrollo<\/h2>\n<ol>\n<li>Anota datos, siglas y unidades.<\/li>\n<li>Identifica el supuesto y escribe la fórmula antes de reemplazar.<\/li>\n<li>Sustituye números y conserva precisión.<\/li>\n<li>Interpreta signo, tamaño, decisión y limitaciones.<\/li>\n<\/ol>\n<p>La pauta del Control 3 exige desarrollo incluso al seleccionar alternativas. Practica la explicación además del número.<\/p>"}, {"topic": "Temario confirmado", "title": "Adquisiciones · procesos y contratos", "body": "<h1>Adquisiciones · PMBOK 6, capítulo 12<\/h1>\n<p>Adquirir implica obtener productos, servicios o resultados externos mediante acuerdos. El contrato obliga a ambas partes: el vendedor entrega lo pactado y el comprador cumple pagos y obligaciones. <strong>El director del proyecto puede participar en la negociación; la firma corresponde a quien tenga autoridad.<\/strong><\/p>\n<h2>Los tres procesos y sus resultados<\/h2>\n<table>\n<thead>\n<tr>\n<th>Proceso<\/th>\n<th>Qué se decide o ejecuta<\/th>\n<th>Entradas, herramientas y salidas<\/th>\n<\/tr>\n<\/thead>\n<tbody>\n<tr>\n<td>Planificar la gestión de adquisiciones<\/td>\n<td>Qué adquirir, cómo y cuándo<\/td>\n<td>Parte de necesidades, alcance, recursos, riesgos, mercado y políticas. Usa análisis hacer/comprar, investigación de mercado y juicio experto. Produce plan, estrategia, SOW, documentos de licitación y criterios de selección.<\/td>\n<\/tr>\n<tr>\n<td>Efectuar adquisiciones<\/td>\n<td>Obtener propuestas, evaluar, negociar y adjudicar<\/td>\n<td>Usa documentos de licitación, criterios y propuestas. Conferencias de oferentes aclaran dudas con información equitativa. El análisis de propuestas y la negociación producen vendedores seleccionados y acuerdos.<\/td>\n<\/tr>\n<tr>\n<td>Controlar adquisiciones<\/td>\n<td>Monitorear obligaciones, gestionar cambios y reclamaciones, cerrar<\/td>\n<td>Usa contratos, datos de desempeño y cambios aprobados. Inspecciones, auditorías y análisis permiten gestionar desviaciones. Produce información de desempeño, cambios y adquisiciones cerradas.<\/td>\n<\/tr>\n<\/tbody>\n<\/table>\n<p><strong>Para recordar: preparar → elegir y acordar → vigilar y cerrar.<\/strong> En PMBOK 6 el cierre contractual está dentro de Controlar las Adquisiciones.<\/p>\n<h2>Hacer o comprar<\/h2>\n<p>Compara capacidad interna, disponibilidad, costo completo, riesgo, plazos, propiedad intelectual y dependencia futura. Un equipo propio que cuesta menos pero retrasa un hito puede resultar peor que contratar.<\/p>\n<p>Ejemplo sin descuento: fabricar internamente cuesta 1.000 de preparación más 20 por unidad. Comprar cuesta 30 por unidad. A 100 unidades ambos cuestan 3.000; a 150, fabricar cuesta 4.000 y comprar 4.500. Verifica capacidad y calidad antes de elegir.<\/p>\n<p><strong>TCO<\/strong> significa costo total de propiedad. Incluye compra, implantación, operación, soporte, renovación, transición y salida. Al comparar muchos años, actualiza los desembolsos.<\/p>\n<h2>Documentos y siglas<\/h2>\n<table>\n<thead>\n<tr>\n<th>Sigla<\/th>\n<th>Significado<\/th>\n<th>Ejemplo de uso<\/th>\n<\/tr>\n<\/thead>\n<tbody>\n<tr>\n<td>RFI<\/td>\n<td>Request for Information, solicitud de información<\/td>\n<td>Desconoces proveedores y soluciones disponibles. Exploras el mercado.<\/td>\n<\/tr>\n<tr>\n<td>RFQ<\/td>\n<td>Request for Quotation, solicitud de cotización<\/td>\n<td>Necesitas precios y condiciones para una compra definida.<\/td>\n<\/tr>\n<tr>\n<td>RFP<\/td>\n<td>Request for Proposal, solicitud de propuesta<\/td>\n<td>Solicitas un enfoque de solución además de precio y capacidades.<\/td>\n<\/tr>\n<tr>\n<td>SOW<\/td>\n<td>Statement of Work, enunciado del trabajo<\/td>\n<td>Define entregables, alcance contratado, cantidades, calidad, ubicación, fechas y servicios adicionales.<\/td>\n<\/tr>\n<tr>\n<td>TOR<\/td>\n<td>Terms of Reference, términos de referencia<\/td>\n<td>En servicios, precisa tareas, coordinación, estándares, datos aportados y revisión.<\/td>\n<\/tr>\n<tr>\n<td>SLA<\/td>\n<td>Service Level Agreement, acuerdo de nivel de servicio<\/td>\n<td>Precisa métrica, objetivo, medición y consecuencias del incumplimiento.<\/td>\n<\/tr>\n<\/tbody>\n<\/table>\n<p>La <strong>estrategia<\/strong> fija entrega, formas contractuales y fases. El <strong>plan<\/strong> organiza actividades, roles, autoridad, calendario, coordinación y control. La oferta del vendedor es evaluada; la adjudicación culmina en el acuerdo.<\/p>\n<h2>Tipos de contrato<\/h2>\n<table>\n<thead>\n<tr>\n<th>Tipo<\/th>\n<th>Pago y asignación de riesgo<\/th>\n<th>Cuándo considerarlo<\/th>\n<\/tr>\n<\/thead>\n<tbody>\n<tr>\n<td>FFP, precio fijo cerrado<\/td>\n<td>Precio acordado para alcance definido; sobrecostos propios recaen principalmente en vendedor<\/td>\n<td>Requisitos estables<\/td>\n<\/tr>\n<tr>\n<td>FPIF, precio fijo con incentivo<\/td>\n<td>Objetivos, fórmula de incentivo y precio máximo<\/td>\n<td>Interesa premiar desempeño medible y compartir desviaciones según contrato<\/td>\n<\/tr>\n<tr>\n<td>FPEPA, precio fijo con ajuste económico<\/td>\n<td>Ajustes predefinidos por índices o condiciones<\/td>\n<td>Plazos largos y exposición a inflación o monedas<\/td>\n<\/tr>\n<tr>\n<td>CPFF, costos más honorarios fijos<\/td>\n<td>Reembolso de costos autorizados más un honorario fijo<\/td>\n<td>Alcance incierto; comprador asume más riesgo de costo<\/td>\n<\/tr>\n<tr>\n<td>CPIF, costos más incentivo<\/td>\n<td>Reembolso más honorarios ajustados mediante reparto pactado<\/td>\n<td>Alinear eficiencia con incertidumbre de alcance<\/td>\n<\/tr>\n<tr>\n<td>CPAF, costos más honorarios por desempeño<\/td>\n<td>Honorario depende de evaluación de criterios de desempeño del comprador<\/td>\n<td>Desempeño difícil de reducir a una fórmula totalmente objetiva<\/td>\n<\/tr>\n<tr>\n<td>T&amp;M, tiempo y materiales<\/td>\n<td>Tarifa fija por unidad, cantidad variable; conviene poner límites y controles<\/td>\n<td>Expertos o personal cuando cuesta definir el trabajo completo al inicio<\/td>\n<\/tr>\n<\/tbody>\n<\/table>\n<p><strong>Fijo se refiere al precio o al honorario según el nombre.<\/strong> En CPFF el honorario puede ser fijo y el total pagado aumentar por costos reembolsables.<\/p>\n<p>Ejemplo de incentivo, con reparto explícito de ahorro: costo objetivo 1.000, honorario objetivo 100 y 20 % del ahorro para vendedor. Si el costo real autorizado es 900, ahorra 100, honorario final 120 y pago total 1.020. Aplica topes o mínimos si el contrato los contiene.<\/p>\n<h2>Selección, cambios y cierre<\/h2>\n<p>Define antes los criterios y ponderaciones: técnica, costo del ciclo de vida, personal, experiencia, entrega y estabilidad financiera. Las conferencias de oferentes deben proporcionar un entendimiento común. Una oferta anormalmente baja requiere analizar si omite trabajo.<\/p>\n<p>Una <strong>reclamación<\/strong> aparece cuando las partes discrepan sobre un cambio o su compensación. Documenta hechos y aplica negociación y mecanismos contractuales de resolución. Un acuerdo verbal informal no basta para actualizar obligaciones contractuales.<\/p>\n<p>Para cerrar, revisa entregables aceptados, obligaciones, pagos, facturas y reclamaciones pendientes. El administrador autorizado comunica formalmente por escrito el cierre. Conserva registros y lecciones.<\/p>\n<p><strong>Caso para pensar.<\/strong> Un proveedor termina el software pero falta entregar los manuales pactados. La funcionalidad terminada no agota las obligaciones del contrato; verifica documentación y aceptación antes de cerrar.<\/p>"}, {"topic": "Temario confirmado", "title": "Costos · procesos y reservas", "body": "<h1>Gestión de costos · PMBOK 6, capítulo 7<\/h1>\n<h2>Cuatro procesos conectados<\/h2>\n<table>\n<thead>\n<tr>\n<th>Proceso<\/th>\n<th>Pregunta<\/th>\n<th>Resultado principal<\/th>\n<\/tr>\n<\/thead>\n<tbody>\n<tr>\n<td>Planificar<\/td>\n<td>¿Con qué reglas estimaremos y controlaremos?<\/td>\n<td>Plan de gestión de costos<\/td>\n<\/tr>\n<tr>\n<td>Estimar<\/td>\n<td>¿Cuánto costarán recursos y trabajo?<\/td>\n<td>Estimaciones y bases de estimación<\/td>\n<\/tr>\n<tr>\n<td>Determinar presupuesto<\/td>\n<td>¿Cuánto autorizamos y en qué fechas?<\/td>\n<td>Línea base y requisitos de financiamiento<\/td>\n<\/tr>\n<tr>\n<td>Controlar<\/td>\n<td>¿Cómo vamos y cuánto costará terminar?<\/td>\n<td>Información de desempeño, pronósticos y solicitudes de cambio<\/td>\n<\/tr>\n<\/tbody>\n<\/table>\n<p><strong>Plan → estimación → presupuesto → control.<\/strong> Las entradas conectan requisitos, recursos, actividades, riesgos, acuerdos y mercado. La EDT sirve para agregar costos por paquetes; el cronograma ubica el presupuesto en el tiempo.<\/p>\n<h2>Exactitud, precisión y bases<\/h2>\n<p>La precisión define el detalle o redondeo, por ejemplo a UF enteras. La exactitud describe el rango esperado de error. Una estimación temprana puede ser muy incierta aunque tenga muchos decimales.<\/p>\n<p>La base de estimación documenta método, supuestos, restricciones, fuentes, rango y confianza. Ejemplo: “120 HH a 0,6 UF/HH, suponiendo una integración disponible, con rango de ±15 %”. Si falla ese supuesto, debes revisar la estimación.<\/p>\n<p><strong>Análoga<\/strong> usa un proyecto comparable. <strong>Paramétrica<\/strong> aplica costo por unidad. <strong>Ascendente<\/strong> suma componentes detallados. <strong>Tres valores<\/strong> considera optimista, probable y pesimista: promedio triangular con pesos iguales o PERT con peso cuatro al más probable. La guía de fórmulas incluye cálculos.<\/p>\n<h2>Reservas y financiamiento<\/h2>\n<p>Contingencia para riesgos identificados integra la línea base. Gestión cubre trabajo imprevisto dentro del alcance y se añade para obtener el presupuesto total. Su aplicación requiere aprobación para transferir el monto correspondiente a la línea base.<\/p>\n<p>Ejemplo: trabajo 900 + contingencia 100 = línea base 1.000. Reserva de gestión 80 → presupuesto total 1.080. BAC en el análisis de valor ganado corresponde al presupuesto de referencia del trabajo, excluyendo la reserva de gestión.<\/p>\n<p>Conciliar límites de financiamiento exige comparar desembolsos por periodo con fondos disponibles. Que el total alcance no garantiza poder pagar cada mes.<\/p>\n<h2>Control y pronóstico<\/h2>\n<p>PV es trabajo planificado valorizado, EV trabajo realizado valorizado y AC costo real. El avance se pondera por presupuesto. Un trabajo anticipado puede tener EV positivo y PV cero. AC puede incluir costos incurridos aún no pagados; la tesorería sigue fechas de pago.<\/p>\n<p><strong>“EV primero; S con P; C con A. Variación resta, índice divide.”<\/strong> Los desarrollos de la pauta y la guía explican CV, SV, CPI, SPI, ETC, EAC y TCPI. VAC significa variación al terminar: presupuesto BAC menos pronóstico EAC. VAC negativo anticipa sobrecosto.<\/p>\n<p>El EAC es pronóstico; TCPI expresa eficiencia necesaria para una meta. Si el patrocinador exige BAC, usa BAC como meta aunque el pronóstico sea mayor. La autorización de cambios y las acciones correctivas deben documentarse.<\/p>\n<p>Al finalizar todo el trabajo de la línea base, EV y PV terminan iguales y SPI tiende a uno. Por eso complementa valor ganado con el seguimiento real de fechas para interpretar retrasos al cierre.<\/p>"}, {"topic": "Costos y flujo de caja", "title": "Guía explicada con fórmulas", "body": "<h1>FEP · Guía de estudio para el control 3<\/h1>\n<p>Material base: <strong>FEP07.26 — Gestión de Costos<\/strong> y <strong>FEP08.26 — Evaluación Financiera de Proyectos<\/strong>.<\/p>\n<table>\n<thead>\n<tr>\n<th>Pregunta<\/th>\n<th>Herramienta<\/th>\n<\/tr>\n<\/thead>\n<tbody>\n<tr>\n<td>¿Cuánto debería costar el trabajo?<\/td>\n<td>Estimación, presupuesto y línea base<\/td>\n<\/tr>\n<tr>\n<td>¿Cómo va la ejecución frente al plan?<\/td>\n<td>Valor ganado, variaciones e índices<\/td>\n<\/tr>\n<tr>\n<td>¿Cuánto costará terminar?<\/td>\n<td>EAC, ETC y TCPI<\/td>\n<\/tr>\n<tr>\n<td>¿Cuánta plata hace falta antes de cobrar?<\/td>\n<td>Flujo mensual y saldo acumulado<\/td>\n<\/tr>\n<tr>\n<td>¿El negocio crea valor?<\/td>\n<td>VAN, TIR y PRI<\/td>\n<\/tr>\n<\/tbody>\n<\/table>\n<h2>1. Planificar, estimar y presupuestar<\/h2>\n<p><strong>Planificar costos<\/strong> significa fijar unidades (HH, UF, pesos), precisión (redondeo), exactitud esperada (rango de error), cuentas de control de la EDT, umbrales de variación, reglas para medir avance y frecuencia de informes. Por ejemplo, la regla 50/50 acredita la mitad del valor al iniciar una tarea y la otra mitad al terminar.<\/p>\n<p><strong>Estimar costos<\/strong> significa calcular cuánto costarán los recursos de cada actividad.<\/p>\n<table>\n<thead>\n<tr>\n<th>Técnica<\/th>\n<th>Cómo funciona<\/th>\n<\/tr>\n<\/thead>\n<tbody>\n<tr>\n<td>Análoga<\/td>\n<td>Usar un proyecto similar como referencia. Es rápida y depende de qué tan comparable sea.<\/td>\n<\/tr>\n<tr>\n<td>Ascendente<\/td>\n<td>Estimar componentes pequeños y sumar. Requiere más detalle.<\/td>\n<\/tr>\n<tr>\n<td>Paramétrica<\/td>\n<td>Aplicar una relación de costo por unidad. Ejemplo: 120 HH × 0,6 UF/HH = 72 UF.<\/td>\n<\/tr>\n<tr>\n<td>Tres valores, PERT<\/td>\n<td><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"(optimista + 4 × más probable + pesimista) / 6\"><mfrac><mrow><mi>O<\/mi><mo>+<\/mo><mn>4<\/mn><mo>×<\/mo><mi>M<\/mi><mo>+<\/mo><mi>P<\/mi><\/mrow><mn>6<\/mn><\/mfrac><\/math>. Con 80, 100 y 150 UF resulta 105 UF.<\/td>\n<\/tr>\n<\/tbody>\n<\/table>\n<h3>Cómo aplicar las cuatro técnicas<\/h3>\n<table>\n<thead>\n<tr>\n<th>Técnica<\/th>\n<th>Datos del ejercicio<\/th>\n<th>Cálculo<\/th>\n<\/tr>\n<\/thead>\n<tbody>\n<tr>\n<td>Análoga<\/td>\n<td>Un portal parecido costó 100 UF. El equipo estima que el nuevo costará 20 % más porque tiene mayor alcance.<\/td>\n<td>100 × 1,20 = <strong>120 UF<\/strong>. El ajuste viene del juicio del equipo o de un dato del enunciado. Si ambos proyectos son comparables y se supone que cuestan lo mismo, puedes usar 100 UF como aproximación.<\/td>\n<\/tr>\n<tr>\n<td>Ascendente<\/td>\n<td>Análisis cuesta 15 UF, desarrollo 75 UF y pruebas 30 UF.<\/td>\n<td>15 + 75 + 30 = <strong>120 UF<\/strong>. Si te dan horas y tarifas, calcula primero el costo de cada componente.<\/td>\n<\/tr>\n<tr>\n<td>Paramétrica<\/td>\n<td>Según datos históricos, preparar un informe cuesta 3 UF. El proyecto requiere 40 informes de complejidad comparable.<\/td>\n<td>40 informes × 3 UF/informe = <strong>120 UF<\/strong>. Si te dan el costo y la cantidad histórica, divide para obtener el costo por unidad.<\/td>\n<\/tr>\n<tr>\n<td>Tres valores, PERT<\/td>\n<td>El costo optimista es 80 UF, el más probable 100 UF y el pesimista 150 UF.<\/td>\n<td><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"(80 + 4 × 100 + 150) / 6\"><mfrac><mrow><mn>80<\/mn><mo>+<\/mo><mn>4<\/mn><mo>×<\/mo><mn>100<\/mn><mo>+<\/mo><mn>150<\/mn><\/mrow><mn>6<\/mn><\/mfrac><\/math> = <strong>105 UF<\/strong>. Si el enunciado pide un promedio simple de los tres escenarios, resulta <math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"(80 + 100 + 150) / 3\"><mfrac><mrow><mn>80<\/mn><mo>+<\/mo><mn>100<\/mn><mo>+<\/mo><mn>150<\/mn><\/mrow><mn>3<\/mn><\/mfrac><\/math> = <strong>110 UF<\/strong>.<\/td>\n<\/tr>\n<\/tbody>\n<\/table>\n<p><strong>Cómo reconocerlas en el control.<\/strong> Si partes del costo total de un proyecto parecido, es <strong>análoga<\/strong>. Si sumas partidas estimadas por separado, es <strong>ascendente<\/strong>. Si aplicas un costo por unidad a una cantidad, es <strong>paramétrica<\/strong>. Si ponderas tres escenarios con pesos 1, 4 y 1, es <strong>PERT<\/strong>. La análoga requiere justificar el ajuste cuando corresponda. Para las otras, el enunciado debe aportar los componentes, el parámetro o los tres valores.<\/p>\n<p>También puedes comparar alternativas como comprar o arrendar, usar información histórica, consultar al equipo y considerar costos de calidad (prevención, evaluación y fallas).<\/p>\n<p><strong>Determinar el presupuesto<\/strong> consiste en agregar las estimaciones, distribuirlas en el cronograma y conciliar los desembolsos con el financiamiento disponible en cada fecha. Si falta caja, se pueden negociar hitos, reprogramar trabajo o buscar fondos adicionales.<\/p>\n<ul>\n<li><strong>Contingencia:<\/strong> cubre riesgos identificados e inciertos. Se incluye en la línea base de costos y el director del proyecto puede gestionarla según el plan.<\/li>\n<li><strong>Gestión:<\/strong> cubre trabajo imprevisto. Se añade a la línea base para formar el presupuesto total. Su uso requiere aprobación y la parte aprobada se incorpora a la línea base.<\/li>\n<li><strong>Línea base de costos:<\/strong> presupuesto aprobado distribuido en el tiempo. Su acumulado suele dibujarse como una <strong>curva S<\/strong>. Alcance (EDT), cronograma y costo integran la línea base de medición del desempeño.<\/li>\n<\/ul>\n<h2>2. Valor ganado<\/h2>\n<table>\n<thead>\n<tr>\n<th>Sigla<\/th>\n<th>Qué mide<\/th>\n<th>Cómo obtenerlo<\/th>\n<\/tr>\n<\/thead>\n<tbody>\n<tr>\n<td><strong>BAC<\/strong><\/td>\n<td>Presupuesto total de referencia<\/td>\n<td>Dato o suma de paquetes<\/td>\n<\/tr>\n<tr>\n<td><strong>PV<\/strong><\/td>\n<td>Valor presupuestado del trabajo que debía estar listo a la fecha<\/td>\n<td>Línea base al corte<\/td>\n<\/tr>\n<tr>\n<td><strong>EV<\/strong><\/td>\n<td>Valor presupuestado del trabajo realizado a la fecha<\/td>\n<td>Presupuesto × avance real, ponderado por paquete<\/td>\n<\/tr>\n<tr>\n<td><strong>AC<\/strong><\/td>\n<td>Costo real incurrido a la fecha<\/td>\n<td>Dato o suma de gastos reales<\/td>\n<\/tr>\n<\/tbody>\n<\/table>\n<p>En ejercicios con un porcentaje global ya ponderado, usa <strong>PV = BAC × avance planificado<\/strong> y <strong>EV = BAC × avance real<\/strong>. Si el plan indica gasto uniforme, la fracción de tiempo transcurrida sirve para el avance planificado. Si hay paquetes con presupuestos distintos, calcula el EV por separado y suma.<\/p>\n<table>\n<thead>\n<tr>\n<th>Pregunta<\/th>\n<th>Variación<\/th>\n<th>Índice<\/th>\n<\/tr>\n<\/thead>\n<tbody>\n<tr>\n<td>¿Cómo va el cronograma?<\/td>\n<td><strong><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"SV = EV − PV\"><mrow><mi>SV<\/mi><mo>=<\/mo><mrow><mi>EV<\/mi><mo>−<\/mo><mi>PV<\/mi><\/mrow><\/mrow><\/math><\/strong><\/td>\n<td><strong><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"SPI = EV / PV\"><mrow><mi>SPI<\/mi><mo>=<\/mo><mfrac><mi>EV<\/mi><mi>PV<\/mi><\/mfrac><\/mrow><\/math><\/strong><\/td>\n<\/tr>\n<tr>\n<td>¿Cómo va el costo?<\/td>\n<td><strong><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"CV = EV − AC\"><mrow><mi>CV<\/mi><mo>=<\/mo><mrow><mi>EV<\/mi><mo>−<\/mo><mi>AC<\/mi><\/mrow><\/mrow><\/math><\/strong><\/td>\n<td><strong><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"CPI = EV / AC\"><mrow><mi>CPI<\/mi><mo>=<\/mo><mfrac><mi>EV<\/mi><mi>AC<\/mi><\/mfrac><\/mrow><\/math><\/strong><\/td>\n<\/tr>\n<\/tbody>\n<\/table>\n<p><strong>EV va primero<\/strong>. Una variación positiva es favorable, cero indica que vas según el plan y una negativa es desfavorable. Para los índices, el punto de referencia es 1. SV se expresa en la unidad del presupuesto. EV mide trabajo valorizado y AC mide gasto efectivo.<\/p>\n<h3>Ejercicio 1 · Diagnóstico de atraso y sobrecosto<\/h3>\n<p>BAC = 1.000 HH, avance planificado = 50 %, avance real = 30 %, AC = 700 HH.<\/p>\n<ul>\n<li>PV = 500 HH y EV = 300 HH.<\/li>\n<li>SV = −200 HH y SPI = 0,60. Se completó el 60 % del trabajo que se debía haber hecho hasta la fecha.<\/li>\n<li>CV = −400 HH y CPI ≈ 0,43. Por cada HH gastada se obtuvo el equivalente de 0,43 HH presupuestadas.<\/li>\n<\/ul>\n<h3>Ejercicio 2 · Adelanto con gasto favorable<\/h3>\n<p>BAC = $3.000 y gasto planificado uniforme en 6 meses. Al mes 3 se terminaron 6 de 10 unidades de igual presupuesto y se gastaron $1.200.<\/p>\n<ul>\n<li>PV = 3.000 × 3/6 = $1.500.<\/li>\n<li>EV = 3.000 × 6/10 = $1.800.<\/li>\n<li>SV = $300 y SPI = 1,2. El proyecto está adelantado.<\/li>\n<li>CV = $600 y CPI = 1,5. El trabajo realizado costó $600 menos de lo presupuestado.<\/li>\n<\/ul>\n<p>Si una gráfica muestra <strong>AC &gt; EV &gt; PV<\/strong>, el proyecto está adelantado y tiene sobrecosto. Lee cada comparación por separado.<\/p>\n<h2>3. Pronósticos de costo<\/h2>\n<p><strong>EAC<\/strong> es el costo total pronosticado al terminar. <strong>ETC<\/strong> es lo que todavía se estima gastar. Siempre se cumple <strong><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"EAC = AC + ETC\"><mrow><mi>EAC<\/mi><mo>=<\/mo><mrow><mi>AC<\/mi><mo>+<\/mo><mi>ETC<\/mi><\/mrow><\/mrow><\/math><\/strong>. Elige según la frase del enunciado.<\/p>\n<table>\n<thead>\n<tr>\n<th>Supuesto sobre el trabajo que falta<\/th>\n<th>ETC<\/th>\n<th>EAC<\/th>\n<\/tr>\n<\/thead>\n<tbody>\n<tr>\n<td>Se ejecutará al costo presupuestado<\/td>\n<td>BAC − EV<\/td>\n<td><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"AC + (BAC − EV)\"><mrow><mi>AC<\/mi><mo>+<\/mo><mrow><mo>(<\/mo><mrow><mi>BAC<\/mi><mo>−<\/mo><mi>EV<\/mi><\/mrow><mo>)<\/mo><\/mrow><\/mrow><\/math><\/td>\n<\/tr>\n<tr>\n<td>Se mantendrá la eficiencia de costo actual<\/td>\n<td><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"(BAC − EV) / CPI\"><mfrac><mrow><mi>BAC<\/mi><mo>−<\/mo><mi>EV<\/mi><\/mrow><mi>CPI<\/mi><\/mfrac><\/math><\/td>\n<td><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"BAC / CPI\"><mfrac><mi>BAC<\/mi><mi>CPI<\/mi><\/mfrac><\/math><\/td>\n<\/tr>\n<tr>\n<td>Influirán tanto costo como cronograma<\/td>\n<td><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"(BAC − EV) / (CPI × SPI)\"><mfrac><mrow><mi>BAC<\/mi><mo>−<\/mo><mi>EV<\/mi><\/mrow><mrow><mi>CPI<\/mi><mo>×<\/mo><mi>SPI<\/mi><\/mrow><\/mfrac><\/math><\/td>\n<td>AC + ETC<\/td>\n<\/tr>\n<tr>\n<td>Se hizo una nueva estimación detallada<\/td>\n<td>Nueva estimación<\/td>\n<td>AC + nueva estimación<\/td>\n<\/tr>\n<\/tbody>\n<\/table>\n<p>Con BAC = $100.000, AC = $70.000 y EV = $40.000, si el trabajo restante sigue el presupuesto original, <strong>ETC = $60.000 y EAC = $130.000<\/strong>.<\/p>\n<p>En el ejemplo de las cuatro naves, BAC = $4.000, AC = $2.800, PV = $3.000 y EV = $2.500. Si influyen plazo y costo, ETC = 1.500 / [(2.500/2.800) × (2.500/3.000)] = <strong>$2.016<\/strong> usando los índices exactos. La diapositiva marca <strong>$2.031<\/strong>, que es la alternativa más cercana al cálculo exacto. Conserva decimales hasta el final cuando puedas.<\/p>\n<blockquote>\n<p>En la diapositiva que resume los casos, el ETC combinado aparece una vez con CPI × CPI. El EAC de esa misma diapositiva y el ejercicio posterior confirman que el denominador es <strong>CPI × SPI<\/strong>.<\/p>\n<\/blockquote>\n<h3>TCPI · Eficiencia requerida para el trabajo restante<\/h3>\n<p><strong>TCPI = trabajo restante valorizado / fondos disponibles para ese trabajo<\/strong>.<\/p>\n<ul>\n<li>Si la meta es el presupuesto original: <strong><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"(BAC − EV) / (BAC − AC)\"><mfrac><mrow><mi>BAC<\/mi><mo>−<\/mo><mi>EV<\/mi><\/mrow><mrow><mi>BAC<\/mi><mo>−<\/mo><mi>AC<\/mi><\/mrow><\/mfrac><\/math><\/strong>.<\/li>\n<li>Si la meta es el costo final revisado: <strong><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"(BAC − EV) / (EAC − AC)\"><mfrac><mrow><mi>BAC<\/mi><mo>−<\/mo><mi>EV<\/mi><\/mrow><mrow><mi>EAC<\/mi><mo>−<\/mo><mi>AC<\/mi><\/mrow><\/mfrac><\/math><\/strong>.<\/li>\n<\/ul>\n<p>Mayor que 1 implica que hay que producir más de $1 de trabajo presupuestado por cada $1 disponible. Compáralo con el CPI observado para juzgar cuánto tendría que mejorar el desempeño.<\/p>\n<p><strong>Ejemplo con BAC.<\/strong> BAC = $1.000, EV = $600 y AC = $750. TCPI = 400/250 = <strong>1,6<\/strong>.<\/p>\n<p><strong>Ejemplo por paquetes con EAC.<\/strong> Tres paquetes presupuestan $500, $4.000 y $3.000 y llevan 100 %, 75 % y 50 % de avance. BAC = $7.500. EV = 500 + 3.000 + 1.500 = $5.000. Con AC = $4.750 y EAC = $7.125, <strong>TCPI = 2.500/2.375 ≈ 1,05<\/strong>. El numerador siempre se calcula con BAC.<\/p>\n<h2>4. Del cronograma al flujo de caja<\/h2>\n<ul>\n<li><strong>Costo directo:<\/strong> se asigna al proyecto, como horas de desarrollo, licencias específicas o hardware.<\/li>\n<li><strong>Costo indirecto:<\/strong> se prorratea, como arriendo o administración.<\/li>\n<li><strong>Costo por HH:<\/strong> lo que cuesta proveer el recurso. <strong>Tarifa por HH:<\/strong> lo que se cobra al cliente.<\/li>\n<\/ul>\n<p>Para cada periodo suma los recursos × costo unitario y agrega las compras en su fecha de pago. Registra los anticipos, hitos, cuotas y demás cobros en el periodo de percepción.<\/p>\n<p><strong>Flujo neto = cobros − pagos<\/strong>. <strong>Saldo acumulado = saldo anterior + flujo neto<\/strong>.<\/p>\n<p>El saldo acumulado más bajo señala la necesidad máxima de capital antes de financiar. En el ejemplo de clase, el periodo 7 llega a <strong>−USD 6.000<\/strong>. En el periodo 8 se cobran USD 10.000, se pagan USD 400 y el saldo acumulado pasa a <strong>+USD 3.600<\/strong>. El saldo final es <strong>+USD 3.200<\/strong>. Para atravesar el déficit hacen falta al menos USD 6.000 bajo los supuestos del ejercicio. Si se exige caja estrictamente positiva o existen intereses, hace falta más.<\/p>\n<p>En la gráfica de cobros y pagos acumulados, la diferencia vertical entre ambas curvas es la caja. Cuanto más se retrasa un hito, más tiempo se deben financiar los costos que lo preceden.<\/p>\n<h2>5. Matemática financiera<\/h2>\n<p>El costo de oportunidad es el rendimiento sacrificado al destinar el capital al proyecto en vez de usarlo en la mejor alternativa comparable.<\/p>\n<table>\n<thead>\n<tr>\n<th>Concepto<\/th>\n<th>Fórmula<\/th>\n<\/tr>\n<\/thead>\n<tbody>\n<tr>\n<td>Interés simple acumulado<\/td>\n<td><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"I = P × i × n\"><mrow><mi>I<\/mi><mo>=<\/mo><mrow><mi>P<\/mi><mo>×<\/mo><mi>i<\/mi><mo>×<\/mo><mi>n<\/mi><\/mrow><\/mrow><\/math><\/td>\n<\/tr>\n<tr>\n<td>Valor futuro compuesto<\/td>\n<td><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"F = P × (1 + i)^n\"><mrow><mi>F<\/mi><mo>=<\/mo><mrow><mi>P<\/mi><mo>×<\/mo><msup><mrow><mo>(<\/mo><mrow><mn>1<\/mn><mo>+<\/mo><mi>i<\/mi><\/mrow><mo>)<\/mo><\/mrow><mi>n<\/mi><\/msup><\/mrow><\/mrow><\/math><\/td>\n<\/tr>\n<tr>\n<td>Valor presente<\/td>\n<td><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"P = F / (1 + i)^n\"><mrow><mi>P<\/mi><mo>=<\/mo><mfrac><mi>F<\/mi><msup><mrow><mo>(<\/mo><mrow><mn>1<\/mn><mo>+<\/mo><mi>i<\/mi><\/mrow><mo>)<\/mo><\/mrow><mi>n<\/mi><\/msup><\/mfrac><\/mrow><\/math><\/td>\n<\/tr>\n<tr>\n<td>Cuota fija de un préstamo<\/td>\n<td><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"A = P × i × (1 + i)^n / [(1 + i)^n − 1]\"><mrow><mi>A<\/mi><mo>=<\/mo><mrow><mi>P<\/mi><mo>×<\/mo><mfrac><mrow><mi>i<\/mi><mo>×<\/mo><msup><mrow><mo>(<\/mo><mrow><mn>1<\/mn><mo>+<\/mo><mi>i<\/mi><\/mrow><mo>)<\/mo><\/mrow><mi>n<\/mi><\/msup><\/mrow><mrow><msup><mrow><mo>(<\/mo><mrow><mn>1<\/mn><mo>+<\/mo><mi>i<\/mi><\/mrow><mo>)<\/mo><\/mrow><mi>n<\/mi><\/msup><mo>−<\/mo><mn>1<\/mn><\/mrow><\/mfrac><\/mrow><\/mrow><\/math><\/td>\n<\/tr>\n<\/tbody>\n<\/table>\n<p>P es el capital inicial, i la tasa por periodo y n el número de periodos. Con $1.000, 14 % anual y 3 años, el saldo es <strong>$1.420<\/strong> con interés simple y <strong>$1.481,54<\/strong> con compuesto.<\/p>\n<ul>\n<li>Para convertir una tasa <strong>efectiva anual<\/strong> a mensual, usa <strong><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"(1 + tasa anual)^(1/12) − 1\"><mrow><msup><mrow><mo>(<\/mo><mrow><mn>1<\/mn><mo>+<\/mo><msub><mi>i<\/mi><mtext>anual<\/mtext><\/msub><\/mrow><mo>)<\/mo><\/mrow><mfrac><mn>1<\/mn><mn>12<\/mn><\/mfrac><\/msup><mo>−<\/mo><mn>1<\/mn><\/mrow><\/math><\/strong>. En el ejercicio en UF el enunciado fija 0,5 % mensual para calcular los intereses del préstamo.<\/li>\n<li>En cada cuota, <strong>interés = saldo inicial × tasa<\/strong>, <strong>amortización de deuda = cuota − interés<\/strong> y <strong>saldo final = saldo inicial − amortización<\/strong>.<\/li>\n<li>Ejemplo de clase: préstamo de $215.375 a 12 % por periodo, en 4 cuotas de aproximadamente $70.909. En la primera, interés = $25.845, amortización ≈ $45.064 y saldo ≈ $170.311. A medida que cae el saldo, baja el interés y sube la amortización.<\/li>\n<\/ul>\n<h2>6. Inflación, tasas y tipo de cambio<\/h2>\n<ul>\n<li><strong>Inflación:<\/strong> aumento generalizado y sostenido de precios. Puede venir de mayor demanda, aumento de costos, expansión monetaria o expectativas de alzas. El <strong>IPC<\/strong> mide la variación de precios de la canasta y sirve de base para reajustar la <strong>UF<\/strong>.<\/li>\n<li><strong>TPM:<\/strong> referencia de la política monetaria que influye sobre el costo del crédito. El material distingue sobrecalentamiento (crecimiento rápido con presión inflacionaria), estanflación (actividad débil con inflación alta), reflación (repunte de actividad y precios asociado a estímulos) y recuperación (repunte tras la recesión).<\/li>\n<li><strong>Dólar:<\/strong> una depreciación del peso encarece en CLP los insumos cotizados en USD. La presentación destaca el precio del cobre, el riesgo global, la diferencia de tasas con EE. UU. y el ciclo mundial del dólar.<\/li>\n<li><strong>Nominal y real:<\/strong> (1 + tasa nominal) = (1 + tasa real) × (1 + inflación). Con tasa nominal de 10 % e inflación de 4 %, tasa real = 1,10/1,04 − 1 = <strong>5,77 %<\/strong>. Usa flujos nominales con tasas nominales y flujos reales con tasas reales, a la misma periodicidad.<\/li>\n<\/ul>\n<h2>7. Construir el flujo para evaluar<\/h2>\n<ol>\n<li>Ingresos operacionales − costos operacionales antes de depreciación y amortización = <strong>EBITDA<\/strong>.<\/li>\n<li>EBITDA − depreciación y amortización contable = <strong>EBIT<\/strong>.<\/li>\n<li>Para el flujo puro, calcula el impuesto sobre el resultado operativo gravable según los supuestos. Para el financiado, incorpora además el efecto de los intereses sobre la base imponible.<\/li>\n<li>Resta el impuesto y vuelve a sumar los gastos contables sin desembolso.<\/li>\n<li>Resta inversiones y capital de trabajo cuando se pagan. Suma recuperaciones y el valor de desecho, con el tratamiento tributario del enunciado.<\/li>\n<\/ol>\n<p>Una plataforma de 900 UF pagada al comprarla genera una salida de 900 UF ese mes. Depreciarla en 36 meses reduce el resultado gravable en 25 UF por mes. Esos 25 UF se agregan de vuelta al convertir utilidad en flujo, ya que corresponden al costo contabilizado de la plataforma que se pagó antes.<\/p>\n<table>\n<thead>\n<tr>\n<th>Flujo<\/th>\n<th>Qué incluye y qué pregunta responde<\/th>\n<\/tr>\n<\/thead>\n<tbody>\n<tr>\n<td>Proyecto puro<\/td>\n<td>Operación, impuestos e inversión sin deuda. ¿El negocio crea valor?<\/td>\n<\/tr>\n<tr>\n<td>Inversionista<\/td>\n<td>Efecto del préstamo, intereses y amortización del principal. ¿Cuánto rinde el capital propio?<\/td>\n<\/tr>\n<tr>\n<td>Tesorería<\/td>\n<td>Todos los cobros y desembolsos en sus fechas efectivas, incluido el financiamiento. ¿Alcanza la caja para pagar?<\/td>\n<\/tr>\n<\/tbody>\n<\/table>\n<p>El préstamo entra como efectivo y la devolución del principal sale como efectivo. En el modelo del curso, el principal se mueve fuera de la base imponible y los intereses se consideran al calcular el impuesto del flujo financiado.<\/p>\n<h2>8. Indicadores de evaluación<\/h2>\n<h3>VAN · Valor Actual Neto<\/h3>\n<p><strong><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"VAN = −I₀ + Σ [Fₜ / (1 + r)^t]\"><mrow><mi>VAN<\/mi><mo>=<\/mo><mrow><mo>−<\/mo><msub><mi>I<\/mi><mn>0<\/mn><\/msub><mo>+<\/mo><munderover><mo>∑<\/mo><mrow><mi>t<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><mi>n<\/mi><\/munderover><mfrac><msub><mi>F<\/mi><mi>t<\/mi><\/msub><msup><mrow><mo>(<\/mo><mrow><mn>1<\/mn><mo>+<\/mo><mi>r<\/mi><\/mrow><mo>)<\/mo><\/mrow><mi>t<\/mi><\/msup><\/mfrac><\/mrow><\/mrow><\/math><\/strong>, donde I₀ es la inversión inicial, Fₜ el flujo neto y r la tasa de descuento por periodo.<\/p>\n<ul>\n<li><strong>VAN &gt; 0:<\/strong> supera la rentabilidad exigida y crea riqueza en dinero de hoy.<\/li>\n<li><strong>VAN = 0:<\/strong> logra exactamente la rentabilidad exigida.<\/li>\n<li><strong>VAN &lt; 0:<\/strong> queda por debajo de la rentabilidad exigida.<\/li>\n<li>Entre alternativas excluyentes y comparables, se elige el <strong>mayor VAN<\/strong>.<\/li>\n<\/ul>\n<p>Ejemplo: inviertes $100 y cobras $120 en un año. A 10 %, VAN = −100 + 120/1,10 = <strong>$9,09<\/strong>. La tasa de descuento representa la rentabilidad mínima exigida, o <strong>TRMA<\/strong>, frente a una alternativa de riesgo comparable. Una tasa mayor reduce el VAN de un proyecto convencional con cobros futuros positivos.<\/p>\n<h3>TIR · Tasa Interna de Retorno<\/h3>\n<p>Es la tasa que hace <strong>VAN = 0<\/strong>. En el ejemplo anterior es <strong>20 %<\/strong>. Para flujos convencionales, si TIR &gt; tasa exigida, VAN &gt; 0. Puedes aproximarla probando tasas hasta que el VAN cambie de signo o con la función TIR de una planilla.<\/p>\n<p>En el ejemplo de las diapositivas, con flujos −350.000, +16.000, +16.000 y +466.000, el <strong>VAN a 7 % es aproximadamente 59.323<\/strong> y la <strong>TIR es aproximadamente 12,96 %<\/strong>.<\/p>\n<p>La TIR puede dar un ranking distinto al VAN si las inversiones o las vidas útiles difieren. Por ejemplo, al 10 %, invertir $1.000 y recibir $2.000 al año da TIR de 100 % y VAN de $818. Invertir $20.000 y recibir $25.000 da TIR de 25 % y VAN de $2.727. Si son excluyentes y se busca maximizar el valor, se elige el segundo. Con varios cambios de signo pueden existir varias TIR, y con todos los flujos positivos puede no existir ninguna.<\/p>\n<h3>PRI, punto de equilibrio y riesgo<\/h3>\n<ul>\n<li><strong>PRI simple:<\/strong> primer periodo en que el acumulado recupera la inversión. En el ejemplo en USD, el acumulado va de −6.000 a +3.600 entre los periodos 7 y 8, por lo que el PRI se alcanza en el periodo 8. Si se usa PRI descontado, se acumulan flujos actualizados.<\/li>\n<li><strong>Punto de equilibrio:<\/strong> nivel de ventas, volumen o momento en que ingresos y costos totales se igualan.<\/li>\n<li><strong>Rentabilidad nominal:<\/strong> proporción calculada sin descontar los flujos. Revisa la base del enunciado. El cuadro de cierre del curso usa margen dividido por costo.<\/li>\n<li><strong>Sensibilidad:<\/strong> cambia un supuesto (precio, demanda, costo o plazo) y observa la variación en VAN, TIR o PRI. También se pueden comparar escenarios pesimista, base y optimista. La matriz de riesgo ordena riesgos por probabilidad e impacto.<\/li>\n<\/ul>\n<h2>9. Ejercicio integrador en UF<\/h2>\n<p>La implementación dura 18 meses. Cuesta <strong>5.000 UF<\/strong> y se vende a <strong>6.000 UF<\/strong>. El markup es (6.000 − 5.000)/5.000 = <strong>20 %<\/strong>. El margen sobre ventas es (6.000 − 5.000)/6.000 = <strong>16,67 %<\/strong>.<\/p>\n<table>\n<thead>\n<tr>\n<th style=\"text-align: right;\">Mes<\/th>\n<th style=\"text-align: right;\">Hito<\/th>\n<th style=\"text-align: right;\">Cobro<\/th>\n<\/tr>\n<\/thead>\n<tbody>\n<tr>\n<td style=\"text-align: right;\">5<\/td>\n<td style=\"text-align: right;\">20 %<\/td>\n<td style=\"text-align: right;\">1.200 UF<\/td>\n<\/tr>\n<tr>\n<td style=\"text-align: right;\">9<\/td>\n<td style=\"text-align: right;\">20 %<\/td>\n<td style=\"text-align: right;\">1.200 UF<\/td>\n<\/tr>\n<tr>\n<td style=\"text-align: right;\">13<\/td>\n<td style=\"text-align: right;\">25 %<\/td>\n<td style=\"text-align: right;\">1.500 UF<\/td>\n<\/tr>\n<tr>\n<td style=\"text-align: right;\">18<\/td>\n<td style=\"text-align: right;\">35 %, aceptación<\/td>\n<td style=\"text-align: right;\">2.100 UF<\/td>\n<\/tr>\n<\/tbody>\n<\/table>\n<ol>\n<li><strong>Sin financiamiento<\/strong>, el saldo llega a <strong>−1.300 UF<\/strong> en los meses 4, 8 y 12. Con los hitos y la compra de una plataforma de 900 UF en el mes 18, la implementación termina con saldo puro de +100 UF antes de impuestos.<\/li>\n<li><strong>Con financiamiento<\/strong>, se prueban 1.300, 1.350 y 1.400 UF. Las primeras dos alternativas dejan saldo negativo. Con 1.400 UF, la empresa aporta 280 y el banco 1.120.<\/li>\n<li><strong>Intereses:<\/strong> 1.120 × 0,5 % = <strong>5,6 UF por mes<\/strong>. En el mes 12, la caja es 1.400 − 1.300 − 12 × 5,6 = <strong>32,8 UF<\/strong>. Se pagan 100,8 UF de intereses en 18 meses y se devuelve el principal al cobrar la aceptación.<\/li>\n<li><strong>Caja al mes 18:<\/strong> 1.400 + 100 − 100,8 − 1.120 = <strong>279,2 UF<\/strong>. Las 1.400 UF corresponden al menor capital entre los montos probados que mantiene la caja positiva.<\/li>\n<li><strong>Operación:<\/strong> meses 19 a 54, con cobro de 175 UF y costo operacional de 125 UF por mes. EBITDA mensual = 50 UF. Depreciación de la plataforma = 25 UF mensuales. EBIT mensual = 25 UF. Con 27 % de impuesto en el enunciado, se debe calcular su base anual y registrar su pago cuando corresponda.<\/li>\n<li><strong>Cuadro nominal:<\/strong> tarifa total de 12.300 UF y costo total de 10.400 UF, incluida la plataforma. Margen del cuadro = 1.900 UF. Margen/costo ≈ <strong>18,3 %<\/strong>. El flujo puro y el flujo del inversionista tienen sus propios VAN y TIR.<\/li>\n<\/ol>\n<h3>Apalancamiento<\/h3>\n<p>Un proyecto de un año cuesta 100 y devuelve 120. Su rentabilidad es 20 %. Si el banco aporta 80 al 10 % y el dueño pone 20, el banco recibe 88 y quedan 32 para el dueño. El dueño gana 12 sobre su aporte de 20, así que su rentabilidad es <strong>60 %<\/strong>.<\/p>\n<p>Si con la misma deuda el proyecto devuelve 105, quedan 17 para el dueño. Pierde 3 sobre 20, o <strong>−15 %<\/strong>. El efecto depende de la diferencia entre la rentabilidad del negocio y el costo de la deuda.<\/p>\n<h2>10. Repaso antes del control<\/h2>\n<p><strong>Si aparecen BAC, PV, EV y AC:<\/strong> calcula plan, avance y gasto al mismo corte. Compara EV con PV para cronograma y con AC para costo. Para pronosticar, identifica el supuesto sobre el trabajo restante. Para TCPI, identifica si la meta es BAC o EAC.<\/p>\n<p><strong>Si aparecen cobros, pagos e inversión:<\/strong> arma primero el flujo por periodo y el acumulado. Encuentra el valle de caja. Luego calcula el VAN con una tasa de la misma periodicidad, identifica la TIR y decide qué flujo corresponde a la pregunta.<\/p>\n<h3>Autoevaluación<\/h3>\n<ol>\n<li>BAC = 2.000, avance planificado = 60 %, avance real = 40 %, AC = 1.000. Calcula PV, EV, SPI y CPI. Interpreta.<\/li>\n<li>Con los mismos datos, ¿cuál es el EAC si se mantiene la eficiencia de costo?<\/li>\n<li>Pagas 100 hoy y recibes 121 en dos años. ¿Cuál es el VAN al 10 % anual?<\/li>\n<li>Cobros acumulados de 2.000 y pagos acumulados de 2.700. ¿Qué aporte adicional lleva la caja a cero?<\/li>\n<li>Una inversión de 900 UF se deprecia en 36 meses. ¿En qué mes registras la salida y cuánto deprecias cada mes?<\/li>\n<li>Con BAC = 7.500, EV = 5.000, AC = 4.750 y EAC = 7.125, calcula TCPI con ambas metas.<\/li>\n<\/ol>\n<h3>Respuestas<\/h3>\n<ol>\n<li>PV = 1.200. EV = 800. SPI ≈ 0,67. CPI = 0,8. Hay atraso y sobrecosto.<\/li>\n<li>EAC = 2.000/0,8 = 2.500.<\/li>\n<li>VAN = −100 + 121/1,1² = 0. El proyecto rinde exactamente 10 %.<\/li>\n<li>\n<ol>\n<li>Para un saldo estrictamente positivo el aporte debe superar 700.<\/li>\n<\/ol>\n<\/li>\n<li>La salida se registra al pagar la compra. La depreciación es 25 UF por mes.<\/li>\n<li>Con BAC: 2.500/2.750 ≈ 0,91. Con EAC: 2.500/2.375 ≈ 1,05.<\/li>\n<\/ol>"}, {"topic": "Temario confirmado", "title": "Lectura 4 · efectos tributarios y legales", "body": "<h1>Lectura · Capítulo 4<\/h1>\n<h1>Aspectos tributarios, legales y administrativos<\/h1>\n<p>Los ejemplos de esta lectura usan tasas y supuestos históricos. Para el certamen aplica los datos del enunciado. El objetivo es explicar efectos económicos, sin convertir sus tasas antiguas en normativa vigente.<\/p>\n<h2>Venta de activos y valor libro<\/h2>\n<p><strong>Valor libro<\/strong> es costo de adquisición menos depreciación acumulada. <strong>Valor de mercado<\/strong> es lo que podría pagarse por el activo. <strong>Residual contable<\/strong> es el valor supuesto al finalizar su vida depreciable. Los tres pueden diferir.<\/p>\n<p>La ganancia gravable de una venta es precio de venta menos valor libro. Si V es precio, VL valor libro y t tasa tributaria, el flujo neto de venta es:<\/p>\n<p><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"Flujo de venta igual a precio de venta menos la diferencia entre precio y valor libro multiplicada por tasa tributaria\"><mrow><mi>FC<\/mi><mo>=<\/mo><mrow><mi>V<\/mi><mo>−<\/mo><mrow><mo>(<\/mo><mrow><mi>V<\/mi><mo>−<\/mo><mi>VL<\/mi><\/mrow><mo>)<\/mo><\/mrow><mo>×<\/mo><mi>t<\/mi><\/mrow><\/mrow><\/math><\/p>\n<p>Ejemplo: V=2.500, VL=2.000 y t=15 %. Ganancia=500; impuesto=75; caja neta=2.425. El valor libro se resta al calcular utilidad y se agrega de vuelta al obtener caja.<\/p>\n<p>Si V=3.000 y VL=4.000 hay pérdida contable de 1.000. Con tasa 15 % y utilidades suficientes para aprovecharla en ese periodo, el ahorro es 150 y el efecto incremental de caja es 3.150. <strong>Una pérdida no garantiza un reembolso inmediato.<\/strong> Verifica la capacidad de absorberla y cuándo se permite usarla según el caso.<\/p>\n<h2>Compra, depreciación, costos e intereses<\/h2>\n<p>Comprar un activo intercambia efectivo por un activo. En el modelo de la lectura, su efecto deducible se distribuye mediante depreciación. Una compra de 9.000 depreciable en tres años produce 3.000 de depreciación anual. A 15 % y con base gravable suficiente, ahorra 450 de impuesto anual.<\/p>\n<p>El ahorro es futuro: para compararlo con la inversión inicial hay que descontarlo. Depreciación acelerada cambia el momento de los ahorros y puede cambiar su valor actual.<\/p>\n<p>Un costo deducible adicional de 200 a tasa de 15 % genera ahorro tributario de 30. El costo neto es 170. Un ahorro de costos también aumenta la base gravable: ahorro bruto 200 deja 170 después de impuestos.<\/p>\n<p>Los intereses deducibles pueden producir escudo tributario. Interés 100 a tasa 20 % deja costo neto de 80 si se aprovecha la deducción. La devolución del principal se registra después del cálculo tributario.<\/p>\n<h2>Pérdidas y análisis incremental<\/h2>\n<p>Compara impuesto total de la empresa <strong>con y sin proyecto<\/strong>. Si la empresa ya tiene utilidades, una pérdida del proyecto puede reducir el pago actual. Si la empresa también tiene pérdidas, el beneficio podría diferirse. Evita contabilizar el mismo crédito fiscal como beneficio de varias alternativas.<\/p>\n<h2>IVA<\/h2>\n<p>El impuesto al valor agregado cobrado en ventas genera débito y el pagado en compras puede generar crédito recuperable, bajo los supuestos de la lectura. Aun siendo recuperable, puede requerir financiamiento entre el pago y la recuperación.<\/p>\n<p>Tres situaciones relevantes: capital de trabajo para financiar IVA de compras; ventas exentas con compras gravadas cuyo crédito no se recupera; e inversiones con IVA elevado y recuperación tardía. El IVA recuperable se separa del costo depreciable. Si no es recuperable, revisa el tratamiento del enunciado.<\/p>\n<h2>Administración y aspectos legales<\/h2>\n<p>Diseñar cargos, remuneraciones, oficinas, sistemas de facturación y cobranza determina inversión inicial y gastos recurrentes. Dimensiona según la operación; revisa crecimiento y reorganización.<\/p>\n<p>La viabilidad legal pregunta si la actividad está permitida y bajo qué condiciones. El análisis económico cuantifica permisos, patentes, contratos, constitución, registros, propiedad intelectual, obligaciones y sus fechas. Un proyecto permitido puede perder rentabilidad por costos de cumplimiento omitidos.<\/p>\n<p><strong>Tip de desarrollo:<\/strong> identifica partida → efecto sobre utilidad → impuesto → movimiento efectivo → año en que ocurre.<\/p>"}, {"topic": "Temario confirmado", "title": "Lectura 7 · construcción de flujos", "body": "<h1>Lectura · Capítulo 7<\/h1>\n<h1>Cómo construir los flujos de caja<\/h1>\n<h2>Horizonte y momento<\/h2>\n<p>El horizonte es el periodo evaluado, que puede ser menor que la vida real del negocio. Año 0 registra compromisos iniciales. Cada flujo se ubica cuando ocurre; si se agregan años, se usa la convención del ejercicio sobre cobros al cierre.<\/p>\n<p>Una vida real mayor exige representar los beneficios posteriores mediante un valor terminal adecuado. Si comparas alternativas de vidas distintas, usa un horizonte compatible o equivalentes anuales con supuestos explícitos de repetición.<\/p>\n<h2>Los cinco pasos<\/h2>\n<ol>\n<li>Ordena ingresos y egresos afectos a impuestos.<\/li>\n<li>Resta gastos contables no desembolsables para calcular utilidad gravable.<\/li>\n<li>Calcula el impuesto y la utilidad neta.<\/li>\n<li>Revierte los gastos sin desembolso previamente deducidos.<\/li>\n<li>Incorpora inversiones, capital de trabajo y otros beneficios o egresos tratados fuera de la utilidad, evitando duplicaciones.<\/li>\n<\/ol>\n<p>Ejemplo: ventas 1.000, operación 500, depreciación 100, impuesto 20 %. Utilidad 400, impuesto 80, utilidad neta 320. Sumando depreciación obtienes 420 de caja operativa. Una reinversión de 200 ese año reduce el flujo a 220.<\/p>\n<h2>Tres finalidades<\/h2>\n<p><strong>Proyecto<\/strong> mide el negocio sin financiamiento. <strong>Inversionista<\/strong> incluye entrada de deuda, intereses y amortización del principal y mide recursos propios. <strong>Capacidad de pago<\/strong> comprueba efectivo disponible para el servicio de deuda. Un valor terminal que solo representa continuidad del negocio no sirve por sí mismo para pagar una cuota.<\/p>\n<p>En el flujo del inversionista, la deuda entra al inicio como financiamiento y reduce el aporte propio. Intereses afectan impuesto si son deducibles; principal se devuelve como caja después del cálculo tributario.<\/p>\n<h2>Leasing<\/h2>\n<p>Permite usar un activo mediante pagos. El contrato puede contemplar compra final, renovación o devolución. La lectura distingue leasing financiero, con compromiso de largo plazo y características de financiación, y operativo, tratado en su ejemplo como alquiler deducible.<\/p>\n<p>En el ejemplo de alquiler deducible, cuota de 100 y tasa tributaria de 20 % implican costo neto 80 con base gravable suficiente. Evita deducir además una depreciación del mismo activo si el esquema del ejercicio asigna el ahorro a la cuota. En leasing financiero distingue el modelo contable del tributario indicado.<\/p>\n<h2>Capital de trabajo, reemplazos y valor terminal<\/h2>\n<p>Capital de trabajo es la inversión en fondos necesarios para operar antes de recuperar cobros. Puede aumentar con las ventas. Registra el incremento cuando se compromete y la recuperación cuando se libera.<\/p>\n<p>Si vendes activos al cierre, incorpora precio menos efecto tributario. El método contable aproxima el remanente por valor libro. El método económico valora capacidad futura de generar beneficios. En este último, no agregues recuperaciones incompatibles con mantener el negocio ni dupliques capital ya incluido en la valoración.<\/p>\n<p>Un reemplazo requiere salida por el equipo nuevo y entrada neta por vender el antiguo. Además cambian operación, depreciaciones, impuestos, futuras reposiciones y valor final.<\/p>\n<h2>Con proyecto menos sin proyecto<\/h2>\n<p>El flujo incremental se calcula por diferencias entre escenarios. La base representa continuar razonablemente sin hacer la inversión. Si el negocio obtiene 10.000 sin proyecto y 13.000 con él, el beneficio incremental es 3.000. Ambos escenarios pueden ser rentables y uno ser mejor.<\/p>\n<p>Si energía baja de 1.000 a 800, el ahorro incremental bruto es 200. Si además pierdes un arriendo de 50 por ocupar un local propio, incorpora ese costo de oportunidad. Los costos iguales en ambos escenarios se cancelan.<\/p>\n<p><strong>Ejemplo de reemplazo:<\/strong> comprar por 5.000, vender antiguo por 1.000 con VL=600 y tasa 25 %. Venta neta=900. Inversión incremental inicial=−4.100. Si ahorras 800/año y la depreciación incremental es 200, mejora de utilidad=600; impuesto adicional=150; flujo incremental=650.<\/p>"}, {"topic": "Temario confirmado", "title": "Lectura 8 · viabilidad económica", "body": "<h1>Lectura · Capítulo 8<\/h1>\n<h1>Cálculo y análisis de viabilidad económica<\/h1>\n<h2>Equivalencias temporales<\/h2>\n<p>Capitalizar lleva un valor hacia el futuro; descontar lo lleva hacia el presente. Para una tasa i y n periodos, VF = VA multiplicado por (1+i) elevado a n. La guía contiene las fórmulas renderizadas.<\/p>\n<p>Una <strong>anualidad<\/strong> es una serie de flujos iguales espaciados regularmente. Su valor actual un periodo antes del primer pago se obtiene con:<\/p>\n<p><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"Valor actual igual a cuota por el factor de valor presente de una anualidad\"><mrow><mi>VA<\/mi><mo>=<\/mo><mrow><mi>C<\/mi><mo>×<\/mo><mfrac><mrow><msup><mrow><mo>(<\/mo><mrow><mn>1<\/mn><mo>+<\/mo><mi>i<\/mi><\/mrow><mo>)<\/mo><\/mrow><mi>n<\/mi><\/msup><mo>−<\/mo><mn>1<\/mn><\/mrow><mrow><mi>i<\/mi><mo>×<\/mo><msup><mrow><mo>(<\/mo><mrow><mn>1<\/mn><mo>+<\/mo><mi>i<\/mi><\/mrow><mo>)<\/mo><\/mrow><mi>n<\/mi><\/msup><\/mrow><\/mfrac><\/mrow><\/mrow><\/math><\/p>\n<p>C representa el pago periódico. Cinco pagos de 100 al 10 % valen 379,08 hoy. Si la serie comienza más tarde, descuenta además el valor calculado hasta el año 0. Para acumular pagos iguales al final del último periodo se usa C multiplicado por el factor de acumulación.<\/p>\n<h2>VAN, TIR y uso de planillas<\/h2>\n<p>VAN suma valores presentes y resta inversión inicial. Es valor adicional sobre el rendimiento exigido. TIR es la tasa que hace VAN cero. En flujos convencionales, TIR mayor que tasa exigida implica VAN positivo.<\/p>\n<p>En Excel, VNA(tasa; flujos desde año 1) se suma al flujo del año 0, que ya está en presente. TIR incluye la secuencia completa desde año 0. Revisa periodicidad y signos.<\/p>\n<p>Cambios de signo múltiples pueden dar varias TIR o ninguna solución útil. Para excluyentes de distinto tamaño, una TIR mayor puede coexistir con menor riqueza creada. Compara VAN bajo supuestos compatibles.<\/p>\n<h2>Recuperación y beneficio/costo<\/h2>\n<p><strong>PRI simple<\/strong> acumula sin descuento. <strong>PRI descontado<\/strong> acumula flujos actualizados, incorporando rendimiento exigido. La lectura desarrolla recuperación considerando ese rendimiento.<\/p>\n<p>Ejemplo: inversión 100 y cobros de 60 en los años 1 y 2. Recupera dentro del segundo año bajo ambos criterios al 10 %, aunque el acumulado actualizado es menor. Si el pago ocurre solo al cierre, informa el periodo. Interpolar una fracción supone distribución dentro del año.<\/p>\n<p>Relación beneficio/costo = valor presente de beneficios dividido por valor presente de costos. Mayor que 1 indica beneficios superiores a costos, con partidas y tasa consistentes. Beneficios presentes de 1.200 y costos de 1.000 → razón 1,2 y VAN 200. Un cociente mayor no garantiza mayor VAN entre alternativas de escala distinta.<\/p>\n<h2>Valor económico agregado y punto de equilibrio<\/h2>\n<p><strong>VEA<\/strong>, valor económico agregado, compara resultado operativo después de impuestos con cargo por capital utilizado. En una formulación básica: resultado neto operativo menos capital invertido por costo de capital. Si resultado=150, capital=1.000 y costo de capital=12 %, VEA=30.<\/p>\n<p>La lectura advierte que mantener capacidad productiva exige reinversiones; incorpora ese efecto cuando se usa un flujo sostenible o perpetuo. Beneficio contable y creación de valor pueden diferir.<\/p>\n<p>Punto de equilibrio operativo en unidades:<\/p>\n<p><math xmlns=\"http://www.w3.org/1998/Math/MathML\" aria-label=\"Cantidad de equilibrio igual a costo fijo dividido por precio menos costo variable unitario\"><mrow><mi>Q<\/mi><mo>=<\/mo><mfrac><mi>CF<\/mi><mrow><mi>p<\/mi><mo>−<\/mo><mi>cv<\/mi><\/mrow><\/mfrac><\/mrow><\/math><\/p>\n<p>CF es costo fijo, p precio y cv costo variable unitario, con p mayor que cv. CF=1.000, p=30, cv=20 → 100 unidades. Cubre costos operativos bajo ese modelo. Para exigir además rendimiento sobre la inversión debes incorporar impuestos, reposición y costo de capital.<\/p>\n<h2>Equivalente anual, perfil y opciones<\/h2>\n<p>Valor anual equivalente distribuye un VAN en una anualidad a la tasa y vida utilizadas. CAE es costo anual equivalente: anualiza el valor presente de costos netos. Entre servicios equivalentes, menor CAE es preferible cuando la comparación y repetición son válidas.<\/p>\n<p>En evaluación de perfil se usan aproximaciones para decidir si profundizar. Un flujo perpetuo sostenible F vale F/i si permanece constante, inicia el próximo periodo y la tasa es positiva. Exige contemplar reinversiones, crecimiento y límites de capacidad antes de aceptar esa simplificación.<\/p>\n<p>Las <strong>opciones reales<\/strong> representan decisiones futuras como esperar, ampliar o abandonar. La flexibilidad puede tener valor ante incertidumbre, pero ese valor requiere estimar escenarios, costos y derechos concretos. La lectura introduce la analogía con opciones de compra: derecho a invertir que puede ejercerse o postergarse.<\/p>\n<p><strong>Tip:<\/strong> primero construye correctamente el flujo y sus supuestos. Una fórmula de VAN bien aplicada a un flujo mal construido sigue dando una decisión equivocada.<\/p>"}], "exam": [{"title": "Adquisición con alcance incierto", "points": 10, "prompt": "Se necesita diagnosticar e integrar un sistema legado sin documentación. Proveedor A ofrece FFP de 800 UF excluyendo interfaces no identificadas. B ofrece T&M a 2 UF/HH con tope de 900 y revisión semanal. Compara alternativas, propone qué información pedir, contenido mínimo del SOW, criterios de selección, controles y condiciones de cierre. Justifica qué aceptarías y con qué condiciones.", "rubric": ["Reconoce incertidumbre y exclusiones; costo total y riesgo no se deducen solo de 800 frente a 900 (2).", "Propone RFI o diagnóstico previo y RFP para enfoques; justifica elección (2).", "SOW con entregables, interfaces, aceptación, responsabilidades y gestión de cambios (2).", "T&M con topes, evidencia de horas, hitos y aprobación; o FFP tras delimitar alcance (2).", "Selección transparente y cierre con entregables aceptados, pagos y reclamaciones resueltos (2)."]}, {"title": "Valor ganado por actividades", "points": 25, "prompt": "Corte al final del mes 4. A: costo 600, meses 1–2, avance 100 %, AC 660. B: costo 1.200, meses 3–6, avance 35 %, AC 500. C: costo 900, meses 4–6, avance 20 %, AC 250. D: costo 300, meses 7–8, avance 10 %, AC 50. Distribución uniforme por actividad. Calcula BAC, PV, EV, AC, CV, SV, CPI y SPI. Explica cómo tratar D.", "rubric": ["BAC=3.000 y PV=600+600+300=1.500 (5).", "EV=600+420+180+30=1.230; AC=1.460 (5).", "CV=−230 y SV=−270 UF (5).", "CPI=0,8425; SPI=0,82; sobrecosto y atraso (5).", "D suma EV y AC reales, pero PV=0 al corte según línea base (5)."]}, {"title": "Pronóstico y exigencia del patrocinador", "points": 15, "prompt": "Usa el caso anterior. Tanto costo como plazo influyen sobre el trabajo restante, pero el patrocinador exige BAC. Calcula ETC, EAC y TCPI para la meta exigida. Compara TCPI con CPI e indica qué cambios tendrían que evaluarse. Usa cocientes sin redondear hasta el final.", "rubric": ["ETC=1.770/[(1.230/1.460)×0,82]≈2.562,17 UF (4).", "EAC=1.460+ETC≈4.022,17 UF (4).", "TCPI=1.770/(3.000−1.460)=1,1494 (4).", "Mejora relativa de eficiencia≈36,43 %. Analizar alternativas de productividad, alcance aprobado y financiamiento (3)."]}, {"title": "Flujo económico y sensibilidad", "points": 20, "prompt": "Proyecto de 3 años. Año 0: equipos 5.000, software 3.000, capital de trabajo 1.000 UF. Estudio irrecuperable ya pagado 400. Ingresos 5.500, 6.500 y 7.000; operación 2.200, 2.500 y 2.700. Sueldo sacrificado 800 por año. Al final del año 3 se vende equipo por 900 y se recupera todo el capital de trabajo. Sin impuestos ni depreciación; tasa 10 %. Construye flujo, nominal y VAN. Recalcula si ingresos del año 1 caen 40 %, sin recuperación posterior.", "rubric": ["Excluye 400 hundidos e incluye 800 de oportunidad anuales (4).", "Flujos −9.000; 2.500; 3.200; 5.400 (5).", "Nominal=2.100; VAN≈−25,54 UF; no cubre el 10 % (5).", "Caída de 2.200 en año 1: flujo=300, nominal=−100; VAN≈−2.025,54 (4).", "Interpreta correctamente descuento y decisión (2)."]}, {"title": "Crédito con gracia", "points": 15, "prompt": "Se financian 9.000 UF a 12 % nominal anual dividido por 12, con 3 meses sin pagos e interés capitalizado. Primera cuota al final del mes 4. Compara 12 y 18 cuotas. Calcula saldo al finalizar gracia, cuota e intereses totales desde el desembolso original. Redondea solo resultados finales.", "rubric": ["i=1 % mensual; P=9.000×1,01³=9.272,709 UF (3).", "Aplica fórmula de anualidad sobre saldo capitalizado (4).", "12 cuotas≈823,87 UF; intereses≈886,43 UF (3).", "18 cuotas≈565,47 UF; intereses≈1.178,44 UF (3).", "Más plazo reduce cuota pero aumenta interés total (2)."]}, {"title": "Lecturas · reemplazo y efectos tributarios", "points": 15, "prompt": "Empresa con utilidades suficientes evalúa reemplazar equipo. Compra nuevo por 5.000 UF en año 0 y vende antiguo por 1.000, cuyo valor libro es 600. Tasa de impuesto 25 %. Ahorro anual de operación 800 y depreciación incremental anual 200. Sin cambio de ingresos ni capital de trabajo. Calcula inversión inicial neta y flujo incremental operativo. Explica el tratamiento de un estudio hundido de 100 y de IVA recuperable pagado hoy y recuperado en seis meses. Distingue recuperación simple y descontada.", "rubric": ["Venta neta=1.000−(1.000−600)×0,25=900; flujo inicial=−4.100 (4).", "Utilidad incremental=800−200=600; impuesto adicional=150; flujo=600−150+200=650 (4).", "Estudio ya pagado irrecuperable se excluye de la decisión futura (2).", "IVA recuperable genera necesidad temporal de fondos; registrar pago y recuperación para caja (3).", "PRI simple acumula sin actualizar; descontado incorpora tasa exigida (2)."]}]};
const key='fep-certamen3-temario-confirmado-v2';
let saved={};
try{saved=JSON.parse(localStorage.getItem(key)||'{}')}catch(e){}
let state={answers:{},drafts:{},examSubmitted:false,start:null,marks:{},...saved};
const el=id=>document.getElementById(id);
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch(e){el('stats').textContent='El navegador no permite guardar. Mantén esta ventana abierta.'}}
function node(tag,text,cls){let n=document.createElement(tag);n.textContent=text;if(cls)n.className=cls;return n}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{document.querySelectorAll('main>section').forEach(s=>s.classList.toggle('hidden',s.id!==b.dataset.page));document.querySelectorAll('[data-page]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));if(b.dataset.page==='exam')renderExam();window.scrollTo(0,0)});
DATA.lessons.forEach((l,i)=>{let b=node('button',l.title);b.onclick=()=>{el('lesson').innerHTML=l.body;document.querySelectorAll('#lessonList button').forEach((x,j)=>x.setAttribute('aria-pressed',String(j===i)))};el('lessonList').append(b)});
el('lessonList').firstChild.click();
let current=0,chosen=null;
function filtered(){return DATA.questions.map((q,i)=>i).filter(i=>(!el('topic').value||DATA.questions[i].topic===el('topic').value)&&(!el('onlyWrong').checked||(state.answers[i]!==undefined&&state.answers[i]!==DATA.questions[i].answer)))}
function renderQuestion(){
 const ids=filtered();current=Math.max(0,Math.min(current,ids.length-1));const id=ids[current];el('question').replaceChildren();
 const answered=Object.keys(state.answers).length,correct=Object.keys(state.answers).filter(i=>state.answers[i]===DATA.questions[i].answer).length;
 el('stats').textContent=answered+' / 50 répondues · '+correct+' correctas';
 el('stats').textContent=el('stats').textContent.replace('répondues','respondidas');
 el('position').textContent=ids.length? (current+1)+' / '+ids.length:'';
 el('previous').disabled=current===0;el('next').disabled=current>=ids.length-1;
 if(id===undefined){el('question').append(node('p','No hay preguntas para este filtro.'));return}
 const q=DATA.questions[id],done=state.answers[id]!==undefined;chosen=done?state.answers[id]:null;
 const card=node('div','', 'card');card.append(node('p',q.topic+' · Pregunta '+(id+1),'muted'),node('h3',q.prompt));
 const options=node('div','','options');
 q.options.forEach((text,i)=>{let b=node('button',String.fromCharCode(65+i)+'. '+text);b.disabled=done;b.setAttribute('aria-pressed',String(chosen===i));if(done&&i===q.answer)b.classList.add('correct');if(done&&i===chosen&&i!==q.answer)b.classList.add('wrong');b.onclick=()=>{chosen=i;[...options.children].forEach((x,j)=>x.setAttribute('aria-pressed',String(i===j)));check.disabled=false};options.append(b)});card.append(options);
 let label=node('label','Tu razonamiento');let draft=document.createElement('textarea');draft.setAttribute('aria-label','Razonamiento de pregunta '+(id+1));draft.value=state.drafts['q'+id]||'';draft.oninput=()=>{state.drafts['q'+id]=draft.value;save()};label.append(draft);card.append(label);
 let check=node('button','Comprobar','primary');check.disabled=chosen===null||done;check.onclick=()=>{state.answers[id]=chosen;save();renderQuestion()};card.append(check);
 if(done){card.append(node('p',(chosen===q.answer?'Correcto. ':'Revisa tu respuesta. ')+q.explanation,'feedback'))}
 el('question').append(card);
}
el('topic').onchange=el('onlyWrong').onchange=()=>{current=0;renderQuestion()};
el('previous').onclick=()=>{current--;renderQuestion()};el('next').onclick=()=>{current++;renderQuestion()};
el('resetPractice').onclick=()=>{if(confirm('¿Borrar respuestas de práctica? El examen se conserva.')){state.answers={};save();renderQuestion()}};
function renderExam(){
 const body=el('examBody');body.replaceChildren();
 if(!state.start&&!state.examSubmitted){body.append(node('p','Inicia el examen para ver los seis casos.'));return}
 DATA.exam.forEach((q,i)=>{let card=node('div','','card');card.append(node('h3',(i+1)+'. '+q.title+' · '+q.points+' puntos'),node('p',q.prompt));let text=document.createElement('textarea');text.setAttribute('aria-label','Desarrollo '+(i+1));text.placeholder='Datos → fórmula → sustitución → resultado → interpretación';text.value=state.drafts['exam'+i]||'';text.readOnly=state.examSubmitted;text.oninput=()=>{state.drafts['exam'+i]=text.value;save()};card.append(text);
 if(state.examSubmitted){let box=node('div','','feedback');box.append(node('h4','Pauta y criterios de autocorrección'));let ul=document.createElement('ul');q.rubric.forEach(r=>ul.append(node('li',r)));box.append(ul);let label=node('label','Puntaje que te asignas (0–'+q.points+') ');let score=document.createElement('input');score.type='number';score.min=0;score.max=q.points;score.value=state.marks[i]??0;score.oninput=()=>{state.marks[i]=Math.min(q.points,Math.max(0,Number(score.value)||0));save();examScore()};label.append(score);box.append(label);card.append(box)}
 body.append(card)});examScore();
}
function examScore(){el('examResult').textContent=state.examSubmitted?'Autocorrección: '+Object.values(state.marks).reduce((a,b)=>a+b,0)+' / 100 puntos. Revisa cada criterio antes de asignarte puntaje.':''}
el('startExam').onclick=()=>{if(!state.start&&!state.examSubmitted){state.start=Date.now();save()}renderExam()};
el('finishExam').onclick=()=>{if(!state.start||state.examSubmitted)return;const n=DATA.exam.filter((_,i)=>!(state.drafts['exam'+i]||'').trim()).length;if(confirm('¿Entregar el examen? '+n+' casos sin responder. Se mostrará la pauta.')){state.examSubmitted=true;save();renderExam()}};
el('resetExam').onclick=()=>{if(confirm('¿Borrar el desarrollo del examen e iniciar otro intento?')){state.start=null;state.examSubmitted=false;state.marks={};for(let i=0;i<DATA.exam.length;i++)delete state.drafts['exam'+i];save();renderExam()}};
setInterval(()=>{if(state.start&&!state.examSubmitted){let remaining=Math.max(0,5400-Math.floor((Date.now()-state.start)/1000));el('clock').textContent=remaining?String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0'):'Tiempo sugerido cumplido';}else el('clock').textContent=state.examSubmitted?'Entregado':'90:00'},1000);
renderQuestion();renderExam();
